def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform divider with equal-sized panels on either side.
    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            divider = ("h", r)
            break
    if divider is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and c == w - c - 1:
                divider = ("v", c)
                break

    if divider[0] == "h":
        _, k = divider
        a, b = grid[:k], grid[k + 1:]
    else:
        _, k = divider
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    shared = set(x for row in a for x in row) & set(x for row in b for x in row)
    color = next(iter(shared))

    return [
        [3 if a[r][c] == color and b[r][c] == color else color
         for c in range(len(a[0]))]
        for r in range(len(a))
    ]
